 'Initial assessment':[sel('Responsiveness',['Unknown','Alert','Responds to voice','Responds to pain','Unresponsive']),area('Mental status / last known baseline'),sel('Breathing',['Unknown','Normal','Labored','Apnea','Gasping']),pulse(),f('Pulse site'),rhythm(),...vitals(),f('Perfusion / skin / capillary refill'),f('Current oxygen / ventilation support'),sel('Working interpretation',['Uncertain','Primary respiratory failure','Primary arrhythmia','Shock','Cardiac arrest']),area('What is preventing oxygen delivery?')],
