 form.elements.Context.onchange=()=>{form.elements.Drug.innerHTML=drugs[form.elements.Context.value].map(d=>`<option>${esc(d)}</option>`).join('');form.elements['Ordered dose / rate'].value='';form.elements['Actual dose / rate'].value='';form.elements['Dose number'].value=effective().filter(e=>e.type==='Medication'&&e.data.Context===form.elements.Context.value&&e.data.Drug===form.elements.Drug.value&&e.data.Status==='Administered'&&e.data.Delivery==='Bolus').length+1;update();};form.elements.Drug.onchange=()=>{form.elements['Ordered dose / rate'].value='';form.elements['Actual dose / rate'].value='';form.elements['Dose number'].value=effective().filter(e=>e.type==='Medication'&&e.data.Context===form.elements.Context.value&&e.data.Drug===form.elements.Drug.value&&e.data.Status==='Administered'&&e.data.Delivery==='Bolus').length+1;update();};form.addEventListener('input',update);form.addEventListener('change',update);update();
