function openCause(index){if(!canRecord())return;const c=causes[index],prev=effective().filter(e=>e.type==='Reversible cause'&&e.data.Cause===c[1]).at(-1)?.data||{};showDialog(c[1],`<p class="notice">${esc(c[2])}</p><div class="form-grid">${[sel('Status',['Not assessed','Suspected','Supported','Less likely','Unresolved','Treated']),area('Supporting / conflicting evidence'),area('Investigation / corrective treatment'),area('Response / current status')].map(d=>inputField(d,prev[d.label])).join('')}</div>${common()}`,'Record cause update');$('#entry-form').onsubmit=e=>{e.preventDefault();try{const d=formData(),t=eventTime(d);complete('Reversible cause',{Cause:c[1],...d},t);}catch(err){fail(err);}};}
function openCorrection(id){const original=state.events.find(e=>e.id===id);const curr=effective().find(e=>e.id===id)||original;showDialog('Correct an event',`<p class="notice">Original entry stays in the PDF audit trail. Corrections update the working timeline and timers. To change an event’s type, void it and record a replacement.</p><div class="form-grid">${[sel('Correction action',['Amend fields / time','Void event']),f('Reason','text',null,true),f('Corrected event time','datetime-local',null,false,{value:localISO(curr.t)}),f('Correction by (initials)')].map(d=>inputField(d)).join('')}${Object.entries(curr.data).filter(([k])=>!['Performed by','Team member ID','Team color','Team role'].includes(k)).map(([k,v])=>inputField(f('Field: '+k,'textarea'),v)).join('')}${performerControl(curr.data['Team member ID']||'',true)}</div>`,'Record correction');$('#entry-form').onsubmit=e=>{e.preventDefault();try{const d=formData(),t=new Date(d['Corrected event time']).getTime();if(!Number.isFinite(t)||t>Date.now()+1000)throw Error('Choose a valid event time no later than now.');const replacement=Object.fromEntries(Object.entries(d).filter(([k])=>k.startsWith('Field: ')).map(([k,v])=>[k.slice(7),v]));const actor=state.team.find(m=>m.id===d['Team member']);replacement['Performed by']=actor?.name||'Unassigned';replacement['Team member ID']=actor?.id||'';replacement['Team color']=actor?.color||'';replacement['Team role']=actor?.role||'';const voided=d['Correction action']==='Void event';if(!voided&&original.type==='Medication'&&replacement.Status==='Administered'&&replacement.Delivery!=='Infusion stop'&&!(Number(replacement['Actual dose / rate'])>0))throw Error('An administered dose / rate must be a positive number.');append('Correction',{'Original event':original.type,Reason:d.Reason,'Recorder initials':d['Correction by (initials)']},Date.now(),{target:id,replacement,correctedTime:t,voided});$('#dialog').close();modalContext=null;toast('Correction recorded; original retained.');}catch(err){fail(err);}};}
function localISO(t){const d=new Date(t);return new Date(t-d.getTimezoneOffset()*60000).toISOString().slice(0,23);}
function listHTML(){const ev=effective().slice().reverse();return ev.length?ev.map(e=>`<article class="log-item ${e.type==='Medication'?'med':e.type==='Electrical therapy'?'electrical':''}"><div class="log-top"><time>${clock(e.t)}</time><span>${esc(e.data.Status||e.data['Time certainty']||'Actual')}</span></div><h3>${esc(e.type==='Medication'?`${e.data.Drug==='Other'?e.data['Other drug / fluid']:e.data.Drug} · ${e.data.Status}`:e.type==='Reversible cause'?e.data.Cause:e.type)}</h3><p>${esc(summary(e))}</p>${actorBadge(e)}${e.data['Quick entry']?`<button class="small" data-detail="${e.id}">${e.data['Details status']==='Added'?'Edit details':'Add details'}</button>`:''}${e.correction?'<span class="muted">Amended · original retained</span>':''}<details><summary>Details / correction</summary><dl>${Object.entries(e.data).filter(([,v])=>v!=='').map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl><small>Entered ${clock(e.entered)} · ${esc(e.mode||state.run.Mode)}${e.weight?` · ${esc(e.weight)} kg`:''}</small><button class="small" data-correct="${e.id}">Correct entry</button></details></article>`).join(''):`<div class="empty"><span>◷</span><h3>A clear record starts here.</h3><p>Recorded events appear here with their time and details.</p></div>`;}
function summary(e){if(e.type==='Medication')return `${e.data['Actual dose / rate']||'No actual dose'} ${e.data['Actual dose / rate']?e.data['Dose units']:''} · ${e.data.Route} · ${e.data.Delivery}`;if(e.type==='Electrical therapy')return `${e.data.Therapy} · ${e.data['Energy actually delivered (J)']||'—'} J · ${e.data.Rhythm}`;if(e.type==='Reversible cause')return `${e.data.Status} · ${e.data['Supporting / conflicting evidence']||'No evidence entered'}`;return Object.entries(e.data).filter(([k,v])=>v&&!['Missing values','Time certainty','Entry timing','Performed by','Team member ID','Team color','Team role','Recorder initials','Quick entry'].includes(k)).slice(0,3).map(([k,v])=>`${k}: ${v}`).join(' · ');}
function action(label,sub,symbol,cls='',act='form'){return `<button class="action ${cls}" data-action="${act}" data-kind="${esc(label)}"><span class="action-symbol" aria-hidden="true">${symbol}</span><strong>${label}</strong><small>${sub}</small></button>`;}
function tabHTML(){const c=activeCPR();if(state.tab==='Interventions')return `<div class="section-heading"><h2>Record an intervention</h2><button class="small" data-action="form" data-kind="Initial assessment">Initial assessment</button></div><div class="action-grid">${action('Rhythm & pulse','Assessment & vital signs','⌁')}${action('Electrical therapy','Shock · cardioversion · pacing','ϟ','shock')}${action('Medication','Reference & administration','+','','med')}${action('Airway & breathing','Ventilation & procedures','≋')}${action('ROSC','Tap to record · details later','↻','','quick-rosc')}${action('Compressor change','Select person, then tap to log','⇄','','compressor')}</div><div class="secondary-actions"><button data-action="form" data-kind="CPR details">CPR quality</button><button data-action="form" data-kind="Vascular access / procedure">Access / procedure</button><button data-action="quick-rearrest">Rearrest</button><button data-action="form" data-kind="Note">Add note</button></div><div class="support-strip"><strong>Assess circulation, not just the tracing.</strong><span>Log actions as they occur. References never create administration entries.</span></div>`;
 if(state.tab==='H’s & T’s')return `<div class="section-heading"><div><h2>Reversible causes</h2><p class="muted">Evidence, treatment and response remain linked to the timeline.</p></div></div><div class="cause-grid">${causes.map((c,i)=>{const last=effective().filter(e=>e.type==='Reversible cause'&&e.data.Cause===c[1]).at(-1);return `<button class="cause" data-cause="${i}"><span class="cause-letter">${c[0]}</span><span><strong>${esc(c[1])}</strong><small>${i===5?'Explicit pediatric cause · ':''}${esc(last?.data.Status||'Not assessed')}</small></span></button>`;}).join('')}</div>`;
 if(state.tab==='Post-ROSC')return `<div class="section-heading"><h2>After circulation returns</h2></div><div class="reference-box"><strong>${state.run.Mode==='Adult'?'Adult post-arrest reference':'Pediatric post-arrest care'}</strong><p>${state.run.Mode==='Adult'?'Once measurement is reliable: SpO2 90–98%; PaCO2 generally 35–45 mm Hg; MAP at least 65 mm Hg. Record the treating team’s targets and actual values.':'Record age-appropriate blood pressure and oxygenation / ventilation targets selected by the treating team. Adult MAP targets are not applied.'}</p><p>Continue cause-directed care, neurologic / seizure assessment and temperature management. Record each ROSC and rearrest.</p></div><div class="action-grid">${action('Post-ROSC assessment','Vitals, targets & organ support','⌁')}${action('Lab / investigation','Specimen, result & action','+')}${action('Rearrest','Tap to record · details later','↻','','quick-rearrest')}</div>`;
 if(state.tab==='Handoff')return `<div class="section-heading"><h2>Close the loop</h2><span class="badge dark">${state.end?'CLOSED':'IN PROGRESS'}</span></div><div class="action-grid">${action('Handoff / closure','Outcome, rationale & receiving team','✓')}${action('Debrief','Separate quality-review observations','≡')}${action('Export PDF','Complete log & amendment history','↓','','export')}</div><div class="support-strip"><strong>Export is your only saved copy.</strong><span>Closing or reloading this page clears the run. Download the PDF before leaving.</span></div><div class="secondary-actions">${state.end?'<button data-action="reopen">Reopen run</button>':''}<button class="danger-outline" data-action="clear">Clear run &amp; start new</button></div>`;
 return referenceHTML();}
function referenceHTML(){return `<div class="section-heading"><h2>2025 AHA reference</h2><span class="muted">${esc(state.run.Mode)}</span></div><p class="notice">Testing build · Independent clinical validation pending. These summaries and calculators support a trained clinician’s selected treatment; they are not orders or an AHA-endorsed product. Neonatal resuscitation at birth is outside scope.</p><details class="ref-section" open><summary>CPR &amp; ventilation</summary><p>Compression rate 100–120/min, full recoil, minimal interruption; change compressor about every 2 minutes.</p><p>${state.run.Mode==='Adult'?'Adult depth at least 5 cm, avoiding >6 cm. Without advanced airway, 30:2. With advanced airway: continuous compressions and 10 breaths/min.':'Pediatric depth at least one-third chest AP diameter. Without advanced airway: single rescuer 30:2; two rescuers, prepubertal 15:2 and postpubertal 30:2. With advanced airway: 20–30 breaths/min during continuous compressions.'}</p><p>Visible chest rise; avoid overventilation. Waveform capnography confirms and monitors endotracheal tube placement.</p></details>${Object.entries(drugs).map(([g,ds])=>`<details class="ref-section"><summary>${esc(g)}</summary>${ds.map(d=>{const r=doseReference(g,d,state.run.Mode,state.run['Weight (kg)'],1);return `<div class="drug-ref"><h3>${esc(d)}</h3><p>${esc(r.text)} ${r.dose!==null?`Reference first dose: ${fmt(r.dose)} ${r.unit}.`:r.range?`${fmt(r.range[0])}–${fmt(r.range[1])} ${r.unit}.`:''} ${esc(r.calculation)}</p><button class="small" data-med="${esc(d)}" data-group="${esc(g)}">Open medication entry</button></div>`;}).join('')}</details>`).join('')}<details class="ref-section"><summary>Source documents &amp; app behavior</summary><p>${VERSION}. Embedded summaries and calculations work offline. Source links require internet.</p>${sources.map(([n,url])=>`<p><a href="${url}" target="_blank" rel="noopener">${esc(n)}</a></p>`).join('')}<p>Only application files are cached. No run data is sent to a server, local storage, session storage or a database. This does not prevent identifiers being typed into free-text fields; keep entries non-identifying.</p><p>Timers use this device’s clock. Keep the screen awake: browser backgrounding may delay visual reminders. Reminders never document an action automatically.</p></details>`;}
function render(){const c=activeCPR();$('#app').innerHTML=`<header><div class="brand"><span class="brandmark" aria-hidden="true">R</span><div>RESUS RECORD<small>Unified event documentation</small></div></div><div class="header-actions"><span class="badge">TEST BUILD</span><button data-action="export">Export PDF</button></div></header><section class="runbar"><button class="run-name" data-action="details">${esc(state.run['Run name / number']||'Set up run')} <span aria-hidden="true">⌄</span></button><span class="mode-chip">${esc(state.run.Mode)}${state.run['Weight (kg)']?' · '+esc(state.run['Weight (kg)'])+' kg':''}</span><span id="offline-status">${offlineReady?'Offline ready':'Preparing offline access…'}</span><span>Session only · export before leaving</span></section>${teamStrip()}<main class="${state.collapsed?'log-collapsed':''}"><section class="workspace ${state.start?'has-run':''}"><div class="section-heading"><div><p class="eyebrow">LIVE WORKSPACE</p><h1>${state.end?'Run closed.':state.start?'Resuscitation record.':'Ready when you are.'}</h1></div>${!state.start?'<button class="primary" data-action="start">Start run</button>':'<button class="small" data-action="details">Run details</button>'}</div>${quickCPRHTML(c)}${quickReceipt()}<div class="timers"><div class="timer"><span>RUN TIME</span><strong id="run-time">00:00</strong><small>${state.end?'Closed':state.start?'Started '+clock(state.start):'Not started'}</small></div><div class="timer ${c.active?'running':''}" id="cpr-timer"><span>${c.paused?'CPR PAUSE':'CPR CYCLE'}</span><strong id="cpr-time">02:00</strong><small id="cpr-caption">Start CPR to begin</small>${c.active?'<button class="timer-control" data-action="cycle">Reset cycle</button>':''}</div><div class="timer" id="epi-timer"><span>LAST EPINEPHRINE</span><strong id="epi-time">—</strong><small id="epi-caption">No arrest bolus recorded</small></div></div><div id="clock-alert" class="notice warning" ${clockAlert?'':'hidden'}>Device clock changed. Verify event times and timers against the clinical clock.</div><nav aria-label="Record sections">${['Interventions','H’s & T’s','Post-ROSC','Handoff','Reference'].map(t=>`<button class="${state.tab===t?'active':''}" data-tab="${esc(t)}" aria-current="${state.tab===t?'page':'false'}">${esc(t)}</button>`).join('')}</nav><div id="tab-content">${tabHTML()}</div></section><aside aria-label="Event log"><div class="section-heading"><h2>Event log <span class="count">${effective().length}</span></h2><button class="small" data-action="collapse" aria-expanded="${!state.collapsed}">${state.collapsed?'Show log':'Collapse'}</button></div><div class="log-content">${listHTML()}</div><div class="log-bottom">Local clock · ${Intl.DateTimeFormat().resolvedOptions().timeZone}<br>Original entries and corrections retained in PDF.</div></aside></main><footer><span>2025 AHA reference · Clinical validation pending</span><span id="wake-status">${wake?'Screen wake lock active':'Keep this page open and screen awake'}</span></footer>`;wire();tick();}
function wire(){document.querySelectorAll('[data-actor]').forEach(b=>b.onclick=()=>{state.activeActor=b.dataset.actor;render();});document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>openQuickDetails(b.dataset.detail));document.querySelectorAll('[data-undo]').forEach(b=>b.onclick=()=>undoQuick(b.dataset.undo));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action,b.dataset.kind));document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;render();});document.querySelectorAll('[data-cause]').forEach(b=>b.onclick=()=>openCause(Number(b.dataset.cause)));document.querySelectorAll('[data-correct]').forEach(b=>b.onclick=()=>openCorrection(b.dataset.correct));document.querySelectorAll('[data-med]').forEach(b=>b.onclick=()=>openMedication({Context:b.dataset.group,Drug:b.dataset.med}));}
function act(a,k){if(a==='team')return openTeam();if(['cpr-start','cpr-pause','cpr-stop','quick-rosc','quick-rearrest','compressor'].includes(a))return quickAction(a);if(a==='form')return openForm(k);if(a==='med')return openMedication();if(a==='details')return openForm('Run details');if(a==='start')return startRun();if(a==='collapse'){state.collapsed=!state.collapsed;render();return;}if(a==='export')return downloadPDF();if(a==='clear'){showDialog('Clear this run?',`<p class="notice warning">All ${state.events.length} entries will be permanently removed from this page. There is no saved copy in the app. Export the PDF first.</p><label class="check"><input type="checkbox" required> I have exported the PDF or intentionally want to discard this run.</label>`,'Clear run');$('#entry-form').onsubmit=e=>{e.preventDefault();state=initial();lastPDF=null;$('#dialog').close();modalContext=null;render();};return;}
 if(a==='reopen'){state.end=null;append('Run reopened');return;}if(!canRecord())return;if(a==='cycle')append('CPR cycle reset',{'Meaning':'Timing checkpoint only; no assessment inferred','Recorder initials':state.run['Recorder initials']});}

function tick(){const now=Date.now(),c=activeCPR();if($('#run-time'))$('#run-time').textContent=state.start?duration((state.end||now)-state.start):'00:00';if($('#cpr-time')){$('#cpr-time').textContent=c.active?duration(Math.abs(120000-(now-c.cycle))):c.paused?duration(now-c.paused):'02:00';$('#cpr-caption').textContent=c.active?(now-c.cycle>=120000?'2 minutes reached · assess cycle':'Until 2-minute checkpoint'):c.paused?'Interruption in progress':'Start CPR to begin';$('#cpr-timer').classList.toggle('due',c.active&&now-c.cycle>=120000);}
 const epi=latestEpi();if($('#epi-time')){$('#epi-time').textContent=epi?duration((state.end||now)-epi.t):'—';$('#epi-caption').textContent=epi?(now-epi.t>=300000?'5 minutes elapsed · reassess':now-epi.t>=180000?'3–5 min reference window':'Since last recorded arrest bolus'):'No current arrest bolus recorded';$('#epi-timer').classList.toggle('due',!!epi&&now-epi.t>=180000&&!state.end);}
 if(Math.abs((now-wall)-(performance.now()-mono))>5000){clockAlert=true;if($('#clock-alert'))$('#clock-alert').hidden=false;}wall=now;mono=performance.now();}
async function requestWake(){try{if('wakeLock'in navigator&&!wake){wake=await navigator.wakeLock.request('screen');wake.addEventListener('release',()=>{wake=null;if($('#wake-status'))$('#wake-status').textContent='Keep this page open and screen awake';});if($('#wake-status'))$('#wake-status').textContent='Screen wake lock active';}}catch{}}
async function downloadPDF(){if(!state.events.length){toast('Record a run before exporting.');return;}if(modalContext?.dirty){toast('Record or discard the open entry before exporting.');return;}try{toast('Preparing complete PDF…');const bytes=await exportPDF(structuredClone(state),structuredClone(effective()));if(lastPDF)URL.revokeObjectURL(lastPDF);lastPDF=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));const a=document.createElement('a');a.href=lastPDF;a.download=`resus-${(state.run['Run name / number']||'run').replace(/[^a-z0-9_-]/gi,'_')}-${new Date().toISOString().slice(0,10)}.pdf`;a.click();toast('PDF prepared. Confirm it is saved before closing the run.');}catch(e){toast('PDF export failed: '+e.message);}}
window.addEventListener('beforeunload',e=>{if(state.events.length||state.team.length||modalContext?.dirty){e.preventDefault();e.returnValue='';}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){tick();if(state.start&&!state.end)requestWake();}});
window.addEventListener('pageshow',e=>{if(e.persisted){state=initial();render();}});
render();setInterval(tick,250);
if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(async()=>{await navigator.serviceWorker.ready;const cache=await caches.open('resus-shell-v4');offlineReady=!!(await cache.match(new URL('./index.html',location.href)));render();}).catch(()=>{if($('#offline-status'))$('#offline-status').textContent='Offline setup failed · keep connected';});}else $('#offline-status').textContent='Offline reload unavailable in this browser';
// The agent interface exposes only navigation, never clinical actions or doses.
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'open_record_section',title:'Open record section',description:'Navigate to an existing record section without recording a clinical event.',inputSchema:{type:'object',properties:{section:{type:'string',enum:['Interventions','H’s & T’s','Post-ROSC','Handoff','Reference']}},required:['section'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='section')||!['Interventions','H’s & T’s','Post-ROSC','Handoff','Reference'].includes(input.section))throw Error('Unknown section');if($('#dialog').open)throw Error('Complete or cancel the open entry first');state.tab=input.section;render();return{section:state.tab};}})).catch(()=>{});}catch{}}
